xml.Script:
        Colors[0] := '0000C8'; // clBlue
        Colors[1] := '009600'; // clGreen
        Colors[2] := 'FF800A'; // clOrange
        Colors[3] := 'FF00B0'; // clLightViolett
        Colors[4] := 'FFFF00'; // clYellow
        Colors[5] := 'C80000'; // clRed
        clUp      := 'A0A0A0';
        clDown    := '303030';

        D := 0.6;
        H := 1 / 3;
        N := 18;

        for i := 0 to 5 do begin
            x[i] := D * cos(Pi / 3 * (i + 0.5));
            y[i] := D * sin(Pi / 3 * (i + 0.5));
        end;

        // color labels
        R := 0.7;
        R1 := R * 0.8;
        R2 := R * 0.63;
        R3 := R * 0.5;
        L := 0.09;
        W := 2 * L;

// converting coordinates of profile Ufo.vec:
// Size 144x144
// Line 139,-1, 128,13, 62,29, 59,35, 55,39, 49,42, 44,52, 36,63, 25,72, 13,78, 1,79
// Line 44,52, 50,82, 54,82, 49,42
// Line 5,52, 3,82, 1,82, 2,42

        function GetInt(): integer;
        begin
          p := Pos(',', sProfile);
          if p = 0 then begin
            substr := sProfile;
            sProfile := '';
          end else begin
            substr := copy(sProfile, 1, p-1);
            Delete(sProfile, 1, p);
          end;
          Result := StrToInt(substr);
        end;

        // Ufo's profile
        sProfile := '139,-1, 128,13, 62,29, 59,35, 55,39, 49,42, 44,52, 36,63, 25,72, 13,78, 1,79';
        ProfileSize := 144;
        pCount := 0;
        while Length(sProfile) > 0 do begin
          px[pCount] := GetInt / ProfileSize * R;
          pz[pCount] := GetInt / ProfileSize * R;
          Inc(pCount);
        end;

        // Legs profile
        sProfile := '44,52, 50,82, 54,82, 49,42'; // x/z
        lCount := 0;
        while Length(sProfile) > 0 do begin
          lx[lCount] := GetInt / ProfileSize * R;
          lz[lCount] :=-GetInt / ProfileSize * R;
          Inc(lCount);
        end;
        sProfile := '5,52, 3,82, 1,82, 2,42'; // y/z
        lCount := 0;
        while Length(sProfile) > 0 do begin
          ly[lCount] := GetInt / ProfileSize * R;
          GetInt;
          Inc(lCount);
        end;
        for i := 0 to lCount - 1 do begin
          lx[i + lCount] := lx[i];
          ly[i + lCount] :=-ly[i];
          lz[i + lCount] := lz[i];
        end;

        SectorAngle := Pi / 3;
        nSections := N div 6;
        SectionAngle := SectorAngle / nSections;
        sa := sin(SectionAngle);
        ca := cos(SectionAngle);
        ca2 := cos(SectionAngle/2);

        procedure CalcSlice(i);
        begin
            for j := 0 to N - 1 do begin
                sa := sin(SectionAngle * j);
                ca := cos(SectionAngle * j);
                Vx[j]   := px[i] * sa;
                Vy[j]   := px[i] * ca;
                Vz[j]   := pz[i];
                Vx[j+N] := px[i+1] * sa;
                Vy[j+N] := px[i+1] * ca;
                Vz[j+N] := pz[i+1];
            end;
        end;

        function GetZ(XC);
        begin
          Result := pz[1] + (XC / ca2 - px[1]) * (pz[2] - pz[1]) / (px[2] - px[1]);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;
